def verify():
    assert abs(math.sqrt(2) / math.pi - 0.450) < 0.001 and abs(2 * math.sqrt(2) / math.pi - 0.900) < 0.001
    assert abs(3 * math.sqrt(2) / math.pi - 1.350) < 0.001 and abs(3 * math.sqrt(6) / (2 * math.pi) - 1.170) < 0.001
    assert abs(1.35 * 380 - 513) < 0.1 and abs(1.35 * 380 * 0.5 - 256.5) < 1e-9 and abs(0.45 * 100 * (1 + 0) - 45) < 1e-9
    assert abs(12 / 48 - 0.25) < 1e-12 and abs(12 / 0.6 - 20) < 1e-12 and abs((48 - 12) * 0.25 / (100e-6 * 100e3) - 0.9) < 1e-12
    assert abs(4 * 100 / (math.pi * math.sqrt(2)) - 90.03) < 0.01
    assert abs(math.sqrt(3) / (2 * math.sqrt(2)) - 0.612) < 0.001 and abs(0.612 * 0.8 * 600 - 293.8) < 0.2
    assert abs(math.hypot(20, 15) / 100 - 0.25) < 1e-12 and abs(0.9 * 0.95 - 0.855) < 1e-12
    assert 380 * 30 / 60 == 190 and 120 * 30 / 4 == 900 and 40 + 50 * 1.2 == 100


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
